CREATE VIEW "public"."brief_overview" AS (select "submission"."created_at", "submission"."slug", "lead"."name", "lead"."email", "submission"."answers" ->> 'company' as "company", "submission"."answers" ->> 'description' as "description", "submission"."answers" -> 'logo' ->> 'fileName' as "logo_file", "submission"."answers" -> 'logo' ->> 'url' as "logo_url", "submission"."answers" -> 'imagery' ->> 'style' as "look", jsonb_path_query_array("submission"."answers", '$.imagery.photos[*].url') as "photo_urls", coalesce("submission"."answers" -> 'colours' ->> 'paletteId', "submission"."answers" -> 'colours' ->> 'hex') as "colour", "submission"."template_ids", case when "submission"."template_ids" is null then null else array(select '/preview/' || "submission"."slug" || '/' || u.id from unnest("submission"."template_ids") with ordinality as u(id, ord) order by u.ord) end as "design_paths", "submission"."email_sent_at", "submission"."settled_at" from "submission" inner join "lead" on "lead"."identity_hash" = "submission"."identity_hash");